{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Baricitinib, which shares the pyrrolopyrimidine core and sulfonamide motif with the query, has an absolute oral bioavailability of 80% in healthy volunteers, strongly supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Ruxolitinib, a close pyrrolopyrimidine analogue, has an absolute oral bioavailability of 74% in humans, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Sildenafil, a sulfonamide-containing heteroaromatic drug, shows oral bioavailability of 38–41% in fasted healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Bumetanide, a sulfonamide-containing drug, has an absolute oral bioavailability of 0.69 in normal volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "A structurally related pyrazolopyrimidinone sulfonamide analogue has 34% oral bioavailability in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Indacaterol, despite lower structural similarity, has an oral bioavailability of approximately 24%, still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues, especially baricitinib and ruxolitinib sharing the pyrrolopyrimidine core, show oral bioavailability values well above 20% (34–95%). No evidence supports low bioavailability, and the physicochemical prior is favorable for absorption. Therefore the query is predicted to have high absolute oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query molecule.",
    "First-pass metabolism and transporter effects for the query are not directly measured, though close analogues with similar cores show high bioavailability.",
    "The query's exact sulfonamide-cyclobutane combination is not identical to any tested analogue, but transfer scores are high and consistent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

